/** Find matching images from OCR or query text */
export function findMatchingDocsImages(query: string): DocsImageItem[] {
  const q = (query || '').toLowerCase().trim();
  if (!q) return [];
  
  return DOCS_IMAGE_CATALOG.filter((item) => {
    if (item.filename.toLowerCase().includes(q)) return true;
    if (item.book.toLowerCase().includes(q)) return true;
    if (item.description.toLowerCase().includes(q)) return true;
    if (item.sampleText && item.sampleText.toLowerCase().includes(q)) return true;
    return item.sampleKeywords.some((kw) => kw.toLowerCase().includes(q));
  });
}
